use vstd::prelude::*;

verus! {
    // Specification for the copy function
    fn copy(a: &Vec<u64>) -> (b: Vec<u64>)
        requires
            a.len() <= 100, // The input vector's length is at most 100
        ensures
            b.len() == a.len(), // The output vector has the same length as the input
            forall|i: nat| 0 <= i < a.len() ==> b[i] == a[i], // Each element is copied correctly
    {
        let mut b: Vec<u64> = Vec::new(); // Initialize the output vector
        let mut i: nat = 0; // Initialize the index

        // Loop to copy elements from a to b
        while i < a.len() as nat
            invariant
                i <= a.len() as nat, // Index is within bounds of input vector
                b.len() == i, // Length of b is equal to the number of copied elements
                forall|j: nat| 0 <= j < i ==> b[j] == a[j], // Elements copied so far are correct
        {
            // Push the current element from a to b
            b.push(a[i as usize]);
            i = i + 1; // Increment the index
        }
        
        b // Return the copied vector
    }
}

